const G=9.8,N=24,TR=5,R=0.4,L=1.6,PY=0.3,D2R=Math.PI/180;
function tgt(n,seed){return n===0?18:8+((n*37+seed*11)%21);}
function over(s){return s.hit||s.tries<=0;}
function tip(a){return [L*Math.cos(a*D2R),PY+L*Math.sin(a*D2R)];}
function ft(a,v){const vs=v*Math.sin(a*D2R),h=tip(a)[1]-R;return (vs+Math.sqrt(vs*vs+2*G*h))/G;}
function pos(a,v,t){const p=tip(a);return [p[0]+v*Math.cos(a*D2R)*t,Math.max(R,p[1]+v*Math.sin(a*D2R)*t-0.5*G*t*t),0];}
export function initialState({inputs}){return {phase:'ready',t:0,a:inputs.angle,v:inputs.speed,n:0,D:18,tries:TR,miss:null,land:0,hit:false,hint:false};}
export function reduce({state,event,inputs,seed}){const s=state;
if(event.type==='step'){if(s.phase!=='flying')return s;const T=ft(s.a,s.v),t=s.t+1/30;if(t<T)return {...s,t};const land=pos(s.a,s.v,T)[0],miss=land-s.D;return {...s,t:T,phase:'landed',land,miss,tries:s.tries-1,hit:Math.abs(miss)<=0.5};}
if(event.type!=='action')return s;const id=event.id||event.actionId||event.action;
if(id==='launch'){if(s.phase==='flying'||over(s))return s;return {...s,phase:'flying',t:0,a:inputs.angle,v:inputs.speed,hint:false};}
if(id==='reset'){const r={...s,phase:'ready',t:0};return over(s)?{...r,tries:TR,miss:null,hit:false}:r;}
if(id==='newTarget'){const n=s.n+1;let D=tgt(n,seed);if(D===s.D)D=D>20?D-7:D+7;return {...s,n,D,phase:'ready',t:0,tries:TR,miss:null,hit:false,hint:false};}
if(id==='hint')return {...s,hint:!s.hint};return s;}
function hintText(s,inputs){const a=inputs.angle,p=tip(a),dx=s.D-p[0],h=p[1]-R,c=Math.cos(a*D2R),need=Math.sqrt(G*dx*dx/(2*c*c*(dx*Math.tan(a*D2R)+h)));let m;if(need>20)m='Hint: even 20 m/s cannot reach at '+a+'°. Aim closer to 45°';else{m='Hint: at '+a+'° you need about '+need.toFixed(1)+' m/s';if(Math.abs(a-45)>=2)m+=', and about '+(90-a)+'° would land near the same place at that speed';}if(s.miss!==null&&!s.hit)m+='. Your last shot was '+(s.miss<0?'short: go faster or closer to 45°':'long: go slower or farther from 45°');return m+'.';}
export function evaluate({inputs,state}){const s=state||initialState({inputs});const a=s.phase==='ready'?inputs.angle:s.a,th=(a-90)*D2R/2;const nodes={};
nodes.pivot={quaternion:[0,0,Math.sin(th),Math.cos(th)]};nodes.target={position:[s.D,0,0]};
const T=ft(s.a,s.v);nodes.ballN={position:s.phase==='ready'?pos(a,inputs.speed,0):pos(s.a,s.v,s.t)};
for(let k=0;k<N;k++){const tk=T*k/N;const vis=s.phase!=='ready'&&tk<=s.t&&k>0;const p=pos(s.a,s.v,tk);p[1]-=R-0.15;nodes['d'+k]={visible:vis,position:p};}
nodes.landMark={visible:s.phase==='landed'&&!s.hit,position:[s.land,0.3,0]};
const readouts={dist:s.D,tries:s.tries};if(s.miss!==null)readouts.miss=s.miss;
let status='playing',msg;if(s.hit){status='won';msg='Hit! Landed '+Math.abs(s.miss).toFixed(2)+' m from the centre. Press New Target to play again.';}
else if(s.tries<=0&&s.phase==='landed'){status='lost';msg='Out of tries: missed by '+Math.abs(s.miss).toFixed(2)+' m. Press Reset or New Target.';}
else if(s.phase==='flying')msg='Ball in flight…';
else if(s.phase==='landed')msg='Missed: '+Math.abs(s.miss).toFixed(2)+' m '+(s.miss<0?'short':'long')+'. Adjust and press Launch.';
else msg='Target at '+s.D+' m. Set angle and speed, then press Launch.';
if(s.hint&&status==='playing'&&s.phase!=='flying')msg+=' '+hintText(s,inputs);
return {nodes,readouts,goal:{status,message:msg}};}
